import { pathToFileURL } from 'node:url';
const started=new Date().toISOString(), began=performance.now();
const results=[], failures=[];
const key='tgp_refresh_token', OLD='A_OLD_R', NEW='A_NEW_R';
const defer=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve}};
const flush=async(n=120)=>{for(let i=0;i<n;i++) await Promise.resolve()};
const until=async(fn,label)=>{const end=performance.now()+2500;while(!fn()){if(performance.now()>end)throw Error('unexplained wait '+label);await new Promise(r=>setTimeout(r,1))}};
const check=(ok,label)=>{if(!ok)failures.push(label)};
const watchdog=setTimeout(()=>{console.log(JSON.stringify({error:'30s budget exceeded',results}));process.exit(2)},30000);
let activeSession=null,activeArea=null,originalRemove=null,originalSet=null;
try {
 for(const [name,root] of [['candidate','/home/user/workspace/worktrees/s4-r6'],['predecessor','/home/user/workspace/execution/s4-r6/predecessor-88287cff']]){
  const {makeBgMock}=await import(pathToFileURL(root+'/test/helpers/background-mock.js'));
  const mock=makeBgMock({tab:{url:'https://app.truecoach.co/clients',token:'A_SOURCE'}});
  globalThis.chrome=mock.chrome;
  await import(pathToFileURL(root+'/background.js'));
  const session=await import(pathToFileURL(root+'/shared/session.js')); activeSession=session;
  const area=mock.chrome.storage.session; activeArea=area;
  const set=area.set,remove=area.remove; originalSet=set;originalRemove=remove;
  let events=[],pairAck=false,steps=[];
  const send=mock.chrome.runtime.sendMessage;
  mock.chrome.runtime.sendMessage=(m)=>{events.push({kind:m.kind,error:m.lastError??null,generation:session.getSessionGeneration(),stored:mock.sessionMap.get(key)??null,pairAck}); if(m.kind==='auth_required')steps.push('auth_emission');return send(m)};
  const pair=()=>mock.dispatch({kind:'session_established',accessToken:'A_NEW_A',refreshToken:NEW}).then(r=>{pairAck=true;steps.push('pair_ack');return r});
  const start=kind=>mock.dispatch({kind,url:'https://app.truecoach.co/clients',tabId:42,sourceToken:'A_SOURCE'});
  const reset=async()=>{area.set=set;area.remove=remove;await session.clearTokens();await flush();events=[];steps=[];pairAck=false;mock.sent.length=0;};
  const guard=async()=>{await flush();return (await mock.dispatch({kind:'start_import',url:'https://example.invalid/'}))?.ok===true};
  for(const kind of ['start_import','start_ingest'])for(let offset=0;offset<=40;offset++){
   await reset();mock.sessionMap.set(key,OLD);const owner=session.getSessionGeneration();
   const reply=defer(),persist=defer();let entered=false;const requests=[];
   globalThis.fetch=async(url,init)=>{requests.push({url,bearer:init?.headers?.Authorization??null,refresh:JSON.parse(init.body).refresh_token});if(!url.endsWith('/refresh'))throw Error('unexpected preflight request');return reply.promise};
   area.set=async obj=>{entered=true;await persist.promise;return set(obj)};
   const accepted=await start(kind);await flush();if(requests.length!==1)throw Error('preflight refresh missing');
   const pairing=pair();await flush();if(!entered)throw Error('preflight barrier missing');
   reply.resolve(new Response(null,{status:401}));await flush(offset);persist.resolve();const ack=await pairing;await flush();
   const auth=events.filter(e=>e.kind==='auth_required'),terminal=events.filter(e=>e.kind==='status_snapshot').at(-1);
   const stale=auth.some(e=>e.generation!==owner),ownerCurrent=terminal?.generation===owner;
   const stored=mock.sessionMap.get(key),state=await mock.dispatch({kind:'request_session_state'});const released=await guard();
   const row={phase:'preflight',name,kind,offset,owner,auth,terminal,requests,accepted,ack,stored,hasSession:state.hasSession,released,stale};results.push(row);
   check(accepted?.ok&&ack?.ok&&released&&requests.length===1&&requests[0].refresh===OLD&&stored===NEW&&state.hasSession,`${name}/${kind}/${offset}:boundary`);
   if(name==='candidate')check(!stale&&(ownerCurrent?(auth.length===1&&terminal.error==='login required to import'):(auth.length===0&&terminal.error?.includes('session changed'))),`${name}/${kind}/${offset}:report`);
  }
  if(name==='candidate'){
   const modes=[{mode:'current-rejected'},{mode:'current-retry401'},{mode:'B-before-clear'},...[0,1,2,3,4,5,8,12].map(offset=>({mode:'B-queued-after-clear',offset})),{mode:'B-persist-fails',offset:0}];
   for(const kind of ['start_import','start_ingest'])for(const {mode,offset=0} of modes){
    await reset();await session.establishSession('A_OLD_A',OLD);await flush();events=[];steps=[];
    const owner=session.getSessionGeneration(),response=defer(),removed=defer();const requests=[];let clearEntered=false,removes=0,pairing=null,ingests=0;
    area.remove=async k=>{removes++;clearEntered=true;steps.push('clear_enter');await removed.promise;await remove(k);steps.push('clear_remove_done')};
    area.set=async obj=>{steps.push('persist_begin');if(mode==='B-persist-fails'&&obj[key]===NEW)throw Error('synthetic persistence failure');await set(obj);steps.push('persist_done')};
    globalThis.fetch=async(url,init)=>{
     requests.push({url,bearer:init?.headers?.Authorization??null,refresh:url.endsWith('/refresh')?JSON.parse(init.body).refresh_token:null});
     if(url.endsWith('/refresh'))return response.promise;
     if(url.endsWith('/scout/ingest')){ingests++;return new Response(null,{status:401})}
     if(url.endsWith('/scout/progress'))return new Response(null,{status:204});
     if(url.endsWith('/scout/ingest/complete'))throw Error('unexpected settlement after auth stop');
     if(url.endsWith('/organizations'))return Response.json({trainer:{id:1}});
     if(url.includes('/clients?'))return Response.json({clients:[{id:'c1'}]});
     throw Error('unrouted synthetic fetch '+url);
    };
    const accepted=await start(kind);await until(()=>requests.some(r=>r.url.endsWith('/refresh')),'runtime refresh');
    if(mode==='B-before-clear')pairing=Promise.resolve(await pair());
    response.resolve(mode==='current-retry401'?Response.json({access_token:'A_OLD_MINTED'}):new Response(null,{status:401}));
    if(mode!=='B-before-clear'){
     await until(()=>clearEntered,'clear entry');removed.resolve();await flush(offset);
     if(mode.startsWith('B-'))pairing=pair();
    }
    const ack=pairing?await pairing:null;
    await until(()=>events.some(e=>e.kind==='auth_required'||e.error?.includes('session changed')),'runtime terminal');await flush();
    const auth=events.filter(e=>e.kind==='auth_required'),terminal=events.filter(e=>e.kind==='status_snapshot').at(-1),stored=mock.sessionMap.get(key)??null;
    const state=await mock.dispatch({kind:'request_session_state'}),released=await guard();
    const stale=auth.some(e=>e.generation!==owner+1||e.stored!==null);
    const row={phase:'runtime',name,kind,mode,offset,owner,accepted,ack,ingests,removes,auth,terminal,stored,hasSession:state.hasSession,released,stale,steps:[...steps],requests};results.push(row);
    check(accepted?.ok&&released&&!requests.some(r=>r.refresh===NEW||r.bearer==='Bearer A_NEW_A'),`${kind}/${mode}/${offset}:authority`);
    if(mode==='B-before-clear')check(auth.length===0&&removes===0&&stored===NEW&&terminal.error?.includes('session changed')&&state.hasSession,`${kind}/${mode}:obsolete`);
    else check(auth.length===1&&!stale&&removes===1&&terminal.error==='session expired — please sign in again',`${kind}/${mode}/${offset}:genuine-clear`);
    if(mode==='B-queued-after-clear')check(ack?.ok&&stored===NEW&&state.hasSession,`${kind}/${mode}/${offset}:replacement`);
    if(mode==='B-persist-fails')check(ack?.error==='session_persist_failed'&&stored===null&&!state.hasSession,`${kind}/${mode}:failed-persist`);
    if(mode.startsWith('current-'))check(stored===null&&!state.hasSession,`${kind}/${mode}:current-state`);
    if(mode==='current-retry401')check(ingests===2&&requests.some(r=>r.bearer==='Bearer A_OLD_MINTED'),`${kind}/${mode}:retry`);
   }
  }
  area.set=set;area.remove=remove;await session.clearTokens();await flush();
 }
 const pre=results.filter(r=>r.phase==='preflight'&&r.name==='predecessor'),cand=results.filter(r=>r.phase==='preflight'&&r.name==='candidate'),run=results.filter(r=>r.phase==='runtime');
 check(pre.filter(r=>r.stale).length>0,'predecessor discrimination');
 for(const name of ['candidate','predecessor'])for(const kind of ['start_import','start_ingest']){const rows=results.filter(r=>r.phase==='preflight'&&r.name===name&&r.kind===kind);check(rows.some(r=>r.terminal.generation===r.owner)&&rows.some(r=>r.terminal.generation!==r.owner),`${name}/${kind}:both report classes`)}
 console.log(JSON.stringify({started,ended:new Date().toISOString(),durationMs:performance.now()-began,node:process.version,network:false,children:false,framework:false,summary:{candidatePreflight:cand.length,predecessorPreflight:pre.length,candidateStale:cand.filter(r=>r.stale).length,predecessorStale:pre.filter(r=>r.stale).map(r=>`${r.kind}@${r.offset}`),runtimeCases:run.length,runtimeStale:run.filter(r=>r.stale).length},failures,results},null,2));
 process.exitCode=failures.length?1:0;
}catch(error){console.log(JSON.stringify({error:String(error.stack),durationMs:performance.now()-began,results},null,2));process.exitCode=2}
finally{clearTimeout(watchdog);if(activeArea){activeArea.set=originalSet;activeArea.remove=originalRemove;}if(activeSession)await activeSession.clearTokens();}
